#!/usr/bin/env python3
"""Design 2.0 Layers + geometry inspector augmentation."""

def install(html):
    css=r'''<style id="d2-layers-css">
#layers .d2-layer-row{display:grid;grid-template-columns:18px 18px 1fr 20px 20px;align-items:center;gap:3px;padding:5px 3px;border-radius:5px;font:10px Inter,sans-serif;color:#5a564e;cursor:pointer}#layers .d2-layer-row:hover,#layers .d2-layer-row.active{background:#e6dfd1}.d2-drag{cursor:grab;color:#aaa;text-align:center}.d2-layer-type{color:#9a927f;text-align:center}.d2-layer-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.d2-mini{border:0!important;background:transparent!important;padding:2px!important;margin:0!important;color:#8b8579!important;width:auto!important}.d2-mini.on{color:#2c2922!important}.d2-geom{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:8px}.d2-geom label{margin:0!important}.d2-geom input{width:100%;padding:7px 8px;border:1px solid #d9d3c7;border-radius:5px;background:#fbfaf6;font:11px ui-monospace,monospace}.d2-section-title{margin-top:14px;font:600 8px Inter,sans-serif;letter-spacing:.15em;color:#999187}.d2-geom-actions{display:flex;gap:5px}.d2-geom-actions button{margin-top:7px!important}
</style>'''
    panel=r'''<div id="d2-geometry" hidden><div class="d2-section-title">GEOMETRY</div><div class="d2-geom"><label>X<input id="d2-x" type="number"></label><label>Y<input id="d2-y" type="number"></label><label>W<input id="d2-w" type="number" min="1"></label><label>H<input id="d2-h" type="number" min="1"></label></div><div class="d2-geom-actions"><button id="d2-geom-apply">Apply</button><button id="d2-duplicate">Duplicate</button></div></div>'''
    js=r'''<script id="d2-layers-js">(()=>{const gid=id=>document.getElementById(id);let d2dragId=null;function page(){return ws?.pages?.find(p=>p.id===active)}function nodeById(id){return page()?.nodes?.find(n=>n.id===id)}function typeGlyph(n){return n.type==='text'?'T':n.type==='image'?'◇':n.type==='rule'?'—':'□'}async function post(payload){const r=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok){gid('status').textContent='LAYER UPDATE FAILED';return null}ws=await r.json();gid('status').textContent='saved · r'+ws.revision+' · '+active;return ws}function renderD2Layers(){const box=gid('layers'),p=page();if(!box||!p)return;box.innerHTML='';[...(p.nodes||[])].slice().reverse().forEach((n,revIndex)=>{const row=document.createElement('div');row.className='d2-layer-row'+(selected?.id===n.id?' active':'');row.draggable=true;row.dataset.id=n.id;row.innerHTML='<span class="d2-drag">⋮⋮</span><span class="d2-layer-type">'+typeGlyph(n)+'</span><span class="d2-layer-name">'+n.id+'</span><button class="d2-mini '+(n.hidden?'':'on')+'" title="Visibility">'+(n.hidden?'○':'●')+'</button><button class="d2-mini '+(n.locked?'on':'')+'" title="Lock">'+(n.locked?'◆':'◇')+'</button>';const buttons=row.querySelectorAll('button');buttons[0].onclick=async e=>{e.stopPropagation();await post({op:'set_node',page_id:active,id:n.id,patch:{hidden:!n.hidden}});renderD2Layers();gid('canvas').src=canvasUrl()};buttons[1].onclick=async e=>{e.stopPropagation();await post({op:'set_node',page_id:active,id:n.id,patch:{locked:!n.locked}});renderD2Layers();gid('canvas').src=canvasUrl()};row.onclick=()=>select(n.id,'text',n.text??n.title??n.body??'',row);row.ondragstart=e=>{d2dragId=n.id;e.dataTransfer.effectAllowed='move'};row.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move'};row.ondrop=async e=>{e.preventDefault();if(!d2dragId||d2dragId===n.id)return;const nodes=p.nodes||[];const target=nodes.findIndex(x=>x.id===n.id);await post({op:'reorder_node',page_id:active,id:d2dragId,index:target});d2dragId=null;renderD2Layers();gid('canvas').src=canvasUrl()};box.appendChild(row)})}function syncGeom(){const n=nodeById(selected?.id),g=gid('d2-geometry');if(!g)return;g.hidden=!n;if(!n)return;gid('d2-x').value=n.x??0;gid('d2-y').value=n.y??0;gid('d2-w').value=n.w??0;gid('d2-h').value=n.h??''}async function applyGeom(){const n=nodeById(selected?.id);if(!n)return;const patch={x:+gid('d2-x').value,y:+gid('d2-y').value,w:+gid('d2-w').value};if(gid('d2-h').value!=='')patch.h=+gid('d2-h').value;await post({op:'set_node',page_id:active,id:n.id,patch});gid('canvas').src=canvasUrl();renderD2Layers();syncGeom()}gid('d2-geom-apply').onclick=applyGeom;gid('d2-duplicate').onclick=async()=>{if(!selected?.id)return;await post({op:'duplicate_node',page_id:active,id:selected.id});renderD2Layers();gid('canvas').src=canvasUrl()};const oldRenderLayers=renderLayers;renderLayers=function(){oldRenderLayers();renderD2Layers()};const oldSelect=select;select=function(id,field,value,el){oldSelect(id,field,value,el);renderD2Layers();syncGeom()};window.addEventListener('message',e=>{const m=e.data||{};if((m.type==='dore-select'||m.type==='dore-saved')&&(!m.page_id||m.page_id===active))setTimeout(()=>{renderD2Layers();syncGeom()},0)});setTimeout(()=>{renderD2Layers();syncGeom()},50)})()</script>'''
    return html.replace('</head>',css+'</head>',1).replace('<button id="save">Save field</button>','<button id="save">Save field</button>'+panel,1).replace('</body>',js+'</body>',1)
